  @case 'moveTake shifts start; refused on start-collision; returns ok flag'  [harness]  @ 953-964
  @case 'resizeTake writes natural; rendered is min(natural, source, gap)'  [harness]  @ 968-979
  @case 'trimHead walks the start edge in, holding the content and the end still'  [harness]  @ 983-999
  @case 'a head is refused before the origin, at the source end, or onto an occupied start'  [harness]  @ 1002-1013
  @case 'tailQN is the source past the rendered end, whatever shortened the take'  [harness]  @ 1016-1025
  @case 'head, rendered length and tail partition the source'  [harness]  @ 1028-1040
  @case 'a trimmed take is capped by the gap, and regrows to source-minus-head without one'  [harness]  @ 1043-1056
  @case 'trimming the head of a resized take keeps the end where the resize put it'  [harness]  @ 1059-1070
  @case 'splitTake cuts a take into two pooled halves that meet at the cut'  [harness]  @ 1076-1093
  @case 'the lower half inherits the natural, so the pair ends where the whole did'  [harness]  @ 1096-1108
  @case 'splitting a head-trimmed take leaves both halves on the source origin'  [harness]  @ 1111-1125
  @case 'a split is refused on either edge, off the take, and on audio'  [harness]  @ 1128-1141
  @case 'deleteTake removes the item, leaving the other take intact'  [harness]  @ 1145-1156
